-- Exercise catalog expansion: idempotent bulk seed generated from
-- supabase/seed/exercises/*.mjs -- see supabase/seed/README.md.
-- Safe to re-run: every insert is `on conflict do nothing`.

-- New equipment slugs (data only, no schema change) ------------------
on conflict (slug) do nothing;

-- Exercises -------------------------------------------------------------
on conflict (slug) do nothing;

